def test_span_normalization() -> None:
    s = Span(TID.upper(), "F067AA0BA902B7", "n", 10, 25, parent_span_id="0000000000000000")
    assert s.trace_id == TID
    assert s.span_id == "00f067aa0ba902b7"
    assert s.parent_span_id is None
    assert s.duration_micros == 15
    assert Span(TID, "1", "n", 10, 5).duration_micros == 0
    assert Span(TID, "1", "n", 10, 20, duration_micros=7).duration_micros == 7
    assert Span(TID, "1", "n", 1, 2, parent_span_id=" ").parent_span_id is None
    assert Span(TID, "1", "n", 1, 2, parent_span_id="0xAB").parent_span_id == "00000000000000ab"
