def test_native_ids_opt_out() -> None:
    trace_id = "2a1b3c.45.16630000000000001"
    s = NativeSpan(trace_id, "seg-1-0", "n", 1, 2, parent_span_id="", links=[])
    assert (s.trace_id, s.span_id, s.parent_span_id) == (trace_id, "seg-1-0", None)
    child = NativeSpan(trace_id, "seg-1-1", "c", 1, 2, parent_span_id="seg-1-0")
    assert child.parent_span_id == "seg-1-0"
    assert NativeSpan(7, b"\x01", "ints", 1, 2).trace_id == "7"  # type: ignore[arg-type]
    assert NativeSpan(trace_id, b"\x0a", "bytes", 1, 2).span_id == "0a"  # type: ignore[arg-type]
    link = NativeLink(trace_id, "seg-2-0")
    assert (link.trace_id, link.span_id) == (trace_id, "seg-2-0")
    trace = NativeTrace(trace_id, [child, s])
    assert trace.trace_id == trace_id
    assert [x.name for x in trace.spans] == ["n", "c"]
    for bad in ("", "  "):
        with pytest.raises(ValidationError):
            NativeTrace(bad)
        with pytest.raises(ValidationError):
            NativeSpan(trace_id, bad, "n", 1, 2)
    with pytest.raises(ValidationError):
        NativeSpan(True, "x", "n", 1, 2)  # type: ignore[arg-type]
    with pytest.raises(ValidationError):  # the default still validates hex ids
        Span(trace_id, "seg-1-0", "n", 1, 2)


def test_native_ids_json() -> None:
    trace_id = "native-trace"
    full = NativeSpan(trace_id, "seg-1-0", "op", 1, 2, links=[NativeLink(trace_id, "seg-0-0")])
    trace = NativeTrace(trace_id, [full])
    back = NativeTrace.from_json(trace.to_json())
    assert back == trace
    assert isinstance(back.spans[0], NativeSpan)
    assert isinstance(back.spans[0].links[0], NativeLink)
    data = TraceSummary(TID, 0, 0, 0).to_json() | {"traceId": trace_id}
    assert NativeSummary.from_json(data).trace_id == trace_id
    with pytest.raises(ValidationError):
        TraceSummary.from_json(data)


def test_sort_and_tree() -> None:
    root = span("1", "root", 0, 100)
    a = span("3", "a", 10, 20, "1")
    b = span("2", "b", 10, 30, "1")
    grandchild = span("4", "gc", 15, 18, "2")
    orphan = span("5", "orphan", 5, 6, "99")
    selfref = span("6", "self", 50, 60, "6")
    assert [s.name for s in sort_spans([grandchild, a, b, root])] == ["root", "b", "a", "gc"]
    roots = build_tree([grandchild, a, b, root, orphan, selfref])
    assert [n.span.name for n in roots] == ["root", "orphan", "self"]
    assert [c.span.name for c in roots[0].children] == ["b", "a"]
    found = roots[0].find("gc")
    assert found is not None
    assert found.span.span_id == grandchild.span_id
    assert roots[0].find("missing") is None


def test_trace_and_summary() -> None:
    trace = Trace(
        TID,
        [
            span("2", "child", 10, 50, "1", service_name="db"),
            span("1", "root", 0, 40, service_name="api"),
        ],
    )
    assert [s.name for s in trace.spans] == ["root", "child"]
    assert [s.name for s in trace.roots()] == ["root"]
    assert trace.services() == ["api", "db"]
    assert len(trace.tree()) == 1
    summary = TraceSummary.from_trace(trace)
    assert summary == TraceSummary(TID, BASE, 50, 2, "api", "root")
    assert TraceSummary.from_trace(Trace(TID)) == TraceSummary(TID, 0, 0, 0)


def test_search_query_matches() -> None:
    trace = Trace(
        TID,
        [
            span("1", "GET /", 0, 1000, service_name="api", attributes={"http.status": 200}),
            span("2", "query", 100, 200, "1", service_name="db"),
        ],
    )
    start = micros_to_datetime(BASE)
    assert TraceSearchQuery().matches(trace)
    assert TraceSearchQuery(service="db", operation="query").matches(trace)
    assert not TraceSearchQuery(service="db", operation="GET /").matches(trace)
    assert TraceSearchQuery(tags={"http.status": "200"}).matches(trace)
    assert not TraceSearchQuery(tags={"http.status": "500"}).matches(trace)
    assert TraceSearchQuery(min_duration_micros=1000, max_duration_micros=1000).matches(trace)
    assert not TraceSearchQuery(min_duration_micros=1001).matches(trace)
    assert not TraceSearchQuery(max_duration_micros=999).matches(trace)
    assert TraceSearchQuery(start=start, end=start).matches(trace)
    assert not TraceSearchQuery(start=start + timedelta(seconds=1)).matches(trace)
    assert not TraceSearchQuery(end=start - timedelta(seconds=1)).matches(trace)
    assert not TraceSearchQuery().matches(Trace(TID))
    assert TraceSearchQuery().limit == 20


