def test_json_round_trip() -> None:
    full = Span(
        TID,
        "00f067aa0ba902b7",
        "op",
        BASE + 1,
        BASE + 11,
        parent_span_id="00000000000000aa",
        kind="client",
        service_name="svc",
        status=SpanStatus("error", "boom"),
        attributes={"k": ("v", 1), "m": {"n": [1]}},
        events=[SpanEvent("ev", BASE + 5, {"x": 1})],
        links=[SpanLink(TID, "00000000000000bb", {"l": True})],
    )
    data = full.to_json()
    assert data == {
        "traceId": TID,
        "spanId": "00f067aa0ba902b7",
        "parentSpanId": "00000000000000aa",
        "name": "op",
        "kind": "client",
        "serviceName": "svc",
        "startMicros": BASE + 1,
        "endMicros": BASE + 11,
        "durationMicros": 10,
        "status": {"code": "error", "message": "boom"},
        "attributes": {"k": ["v", 1], "m": {"n": [1]}},
        "events": [{"name": "ev", "timeMicros": BASE + 5, "attributes": {"x": 1}}],
        "links": [{"traceId": TID, "spanId": "00000000000000bb", "attributes": {"l": True}}],
    }
    back = Span.from_json(data)
    assert back.to_json() == data
    trace = Trace(TID, [full])
    assert Trace.from_json(trace.to_json()) == Trace(TID, [back])
    minimal = Span.from_json(
        {
            "traceId": TID,
            "spanId": "1",
            "name": "m",
            "startMicros": BASE,
            "endMicros": BASE + 5,
            "status": "ok",
        }
    )
    assert minimal.duration_micros == 5
    assert minimal.status == SpanStatus("ok")
    assert minimal.service_name == "unknown_service"
    assert "parentSpanId" not in minimal.to_json()
    assert minimal.to_json()["status"] == {"code": "ok"}
    no_status = Span.from_json(
        {"traceId": TID, "spanId": "2", "name": "n", "startMicros": 1, "endMicros": 2}
    )
    assert no_status.status == SpanStatus()


