def test_span_from_readable() -> None:
    exporter = InMemorySpanExporter()
    provider = TracerProvider(resource=Resource.create({"service.name": "conv"}))
    provider.add_span_processor(SimpleSpanProcessor(exporter))
    tracer = provider.get_tracer("t")
    link = Link(SpanContext(0xAB, 0xCD, False), {"why": "batch"})
    with (
        tracer.start_as_current_span("parent", kind=SpanKind.SERVER),
        tracer.start_as_current_span(
            "child", links=[link], attributes={"tags": ("a", "b")}
        ) as child,
    ):
        child.add_event("ev", {"n": 1})
        child.set_status(Status(StatusCode.ERROR, "bad"))
    provider.shutdown()
    child_span, parent_span = exporter.spans
    assert parent_span.kind == "server"
    assert parent_span.parent_span_id is None
    assert child_span.parent_span_id == parent_span.span_id
    assert child_span.service_name == "conv"
    assert child_span.attributes == {"tags": ["a", "b"]}
    assert child_span.events[0].name == "ev"
    assert child_span.links[0].trace_id == normalize_trace_id(0xAB)
    assert child_span.status == SpanStatus("error", "bad")
    assert child_span.duration_micros >= 0
    exporter.clear()
    assert exporter.spans == []


def test_span_from_readable_without_service_name() -> None:
    exporter = InMemorySpanExporter()
    provider = TracerProvider(resource=Resource({}))
    provider.add_span_processor(SimpleSpanProcessor(exporter))
    with provider.get_tracer("t").start_as_current_span("x"):
        pass
    assert exporter.spans[0].service_name == "unknown_service"
    exporter.fail = True
    with provider.get_tracer("t").start_as_current_span("y"):
        pass
    assert len(exporter.spans) == 1
    assert exporter.force_flush()
